export function spatialLessons(data){if(!data)return{mask:[],cutout:[],tracking:[]};const mask=data.circles.map(c=>({kind:'circle-window',title:'圆形窗口复现候选',start:c.start,end:c.end,reason:`${c.count} 帧中存在相近圆形边界且内部有纹理。实景圆形物体、贴纸也可能产生相同证据，不能证明原片用了蒙版。`,parameters:`中心横向 ${Math.round(c.x*100)}%、纵向 ${Math.round(c.y*100)}%；直径约为画面宽度 ${Math.round(c.r*200)}%（采样估计）`,steps:['将窗口内的素材放上层叠加轨，主画面放下层。',`选中上层素材 → 蒙版 → 圆形；将中心放在横向 ${Math.round(c.x*100)}%、纵向 ${Math.round(c.y*100)}%，试调直径为画面宽度 ${Math.round(c.r*200)}%。`,'先设羽化为 0，再对照边缘逐步增加；逐帧检查窗口位置、遮挡顺序和内外画面的运动。']}));const people=data.frames.filter(f=>f.person),cutout=people.length>=3?[{kind:'person-matte',title:'人物主体分割与抠像复现',start:people[0].time,end:people.at(-1).time,reason:`模型在 ${people.length} 个采样中提取到人物前景，并显示实际概率遮罩。这是本工具新计算的遮罩，不能证明原片做过抠像；非人物、头发细边和遮挡可能失败。`,parameters:`首个可靠人物框：横向 ${Math.round(people[0].person.box.x*100)}%、纵向 ${Math.round(people[0].person.box.y*100)}%，占宽 ${Math.round(people[0].person.box.w*100)}%、占高 ${Math.round(people[0].person.box.h*100)}%。原抠像参数未知。`,steps:['将人物源素材放到背景上方的叠加轨；打开“抠像 / 移除背景”，选择“智能抠像”。','对照本工具显示的遮罩检查头发、手指与衣服边缘；模型遮罩仅作参考，必要时在剪映补选或擦除。','把背景放到下层，逐帧检查遮挡和边缘溢色；没有独立人物源素材时，无法恢复被成片遮住的背景。']}]:[];const tracking=data.following.map(f=>({kind:'text-follow',title:'文字与局部目标同动候选',start:f.start,end:f.end,reason:`${f.path.length} 个时刻的文字与局部特征点保持近似相对位置，已排除文字框内的自匹配与近似整体平移。仍可能是手动关键帧或实景文字，不证明使用自动跟踪。`,parameters:`目标起点约 ${Math.round(f.path[0].target.x*100)}%, ${Math.round(f.path[0].target.y*100)}%；文字“${f.text}”。`,steps:[`定位 ${f.start.toFixed(2)} 秒，在画面约横向 ${Math.round(f.path[0].target.x*100)}%、纵向 ${Math.round(f.path[0].target.y*100)}% 的目标处设置跟踪区域。`,'选中文字或贴纸，进入“跟踪 / 运动跟踪”（入口随版本变化），分析运动并关联目标；若该版本不支持文字关联，使用位置关键帧复现。',...f.path.filter((_,i)=>i===0||i===f.path.length-1||i%Math.max(1,Math.floor(f.path.length/3))===0).map(p=>`${p.time.toFixed(2)} 秒：文字中心试放横向 ${Math.round(p.text.x*100)}%、纵向 ${Math.round(p.text.y*100)}%；逐帧检查遮挡和漂移。`)]}));return{mask,cutout,tracking}}
